E={
'g-pais-001':(['Urbana tem cidade: muita interferência humana.','Humanizada é a modificada pelas pessoas.','Industrial tem fábricas: humanizada.'],['Paisagem natural: pouca ou nenhuma ação humana.','Paisagem humanizada (cultural): modificada pelas pessoas.'],'Hoje quase não existe paisagem 100% natural; por isso a definição fala em "pouca".'),
'g-pais-002':(['Qualquer ponto do mapa é localização, não lugar.','Relevo é a forma do terreno.','Lugar pode ser pequeno: sua casa, sua rua.'],['Lugar: espaço com o qual temos vínculo e afeto.','Paisagem: o que os sentidos percebem.'],'O mesmo bairro pode ser "lugar" para quem mora e só "paisagem" para um turista.'),
'g-pais-003':(['Não são só as pessoas: chuva e vento também mudam.','Não é só a natureza: construções também mudam.','Paisagens mudam o tempo todo.'],['Paisagem muda pela natureza (chuva, vento, rios) e pela sociedade (construções).'],'Algumas mudanças naturais são lentas demais para percebermos, mas acontecem.'),
'g-pais-004':(['Montanha é natural.','Cachoeira é natural.','Floresta nativa é natural.'],['Elemento cultural: feito ou modificado pelas pessoas.'],'Plantação tem plantas, mas foi organizada por pessoas: é cultural.'),
'g-pais-005':(['É o contrário: espaço geográfico é o transformado pelas pessoas.','Espaço sideral é Astronomia.','Mapa é só a representação do espaço.'],['Espaço geográfico: espaço produzido e transformado pela sociedade.'],'O mapa representa o espaço, mas não é o espaço.'),
'g-pais-006':(['Escala é a proporção do mapa.','Bússola é instrumento de orientação.','Latitude é coordenada geográfica.'],['Paisagem: tudo o que os sentidos percebem (formas, cores, sons, cheiros).'],'Paisagem não é só o que se vê: barulho e cheiro também fazem parte.'),
'g-pais-007':(['Rodovia foi construída.','Prédio foi construído.','Ponte foi construída.'],['Natural: rio, montanha, floresta. Cultural: rodovia, prédio, ponte.'],'Uma represa no rio é cultural; o rio em si é natural.'),
'g-pais-008':(['Natural seria sem ação humana.','Intocada = natural.','Selvagem também sugere natural.'],['Humanizada (cultural): construída ou modificada pelas pessoas.'],'Plantação também é humana, não "natural".'),
'g-orient-001':(['Norte não é onde o Sol nasce.','Sul também não.','Oeste é onde ele se põe.'],['Sol nasce a leste (nascente) e se põe a oeste (poente).'],'É "aproximadamente": o ponto exato varia ao longo do ano.'),
'g-orient-002':(['Sul é oposto do norte.','Sudeste é oposto do noroeste.','Noroeste é oposto do sudeste.'],['Oposto de colateral: troque as duas partes (NE ↔ SO, NO ↔ SE).'],'Não troque só uma parte: o oposto de nordeste não é sudeste.'),
'g-orient-003':(['Sudeste fica entre sul e leste.','Sudoeste fica entre sul e oeste.','Noroeste fica entre norte e oeste.'],['Colaterais: NE, SE, SO, NO.'],'O nome do colateral junta os dois cardeais vizinhos.'),
'g-orient-004':(['Noroeste fica entre norte e oeste.','Nordeste fica entre norte e leste.','Sudeste fica entre sul e leste.'],['Sul + oeste = sudoeste.'],'Sudoeste (SO) às vezes aparece como SW, do inglês southwest.'),
'g-orient-005':(['Leste é onde o Sol nasce.','Norte não é poente.','Sul não é poente.'],['Poente = oeste.'],'Ocidente também quer dizer oeste.'),
'g-orient-006':(['Gnômon usa a sombra do Sol.','Bússola usa o magnetismo, não satélites.','Astrolábio é instrumento antigo de navegação.'],['GPS: localização por satélites.'],'GPS mostra a posição; a bússola mostra a direção.'),
'g-orient-007':(['Latitude é coordenada.','Escala é proporção.','Legenda explica os símbolos do mapa.'],['Rosa dos ventos: pontos cardeais, colaterais e subcolaterais.'],'Cardeais: N, S, L, O. Colaterais: NE, SE, SO, NO.'),
'g-orient-008':(['A agulha não aponta para o sul geográfico.','Leste não.','Ela não aponta para dentro da Terra.'],['Bússola: agulha imantada aponta para o norte magnético.'],'Norte magnético e norte geográfico ficam perto, mas não no mesmo ponto.'),
'g-orient-009':(['Escorpião não indica o sul.','Órion é usada para outras referências.','Ursa Maior quase não aparece no sul e indica o norte.'],['Cruzeiro do Sul: orientação no hemisfério sul.'],'O Cruzeiro está na bandeira do Brasil.'),
'g-orient-010':(['Sul fica às suas costas.','Oeste fica à esquerda.','Leste é para onde aponta o braço direito.'],['Direita = leste; esquerda = oeste; frente = norte; costas = sul.'],'Se o braço ESQUERDO apontar para o nascente, você fica de frente para o sul.'),
'g-coord-001':(['O Brasil está quase todo ao sul do Equador e a oeste de Greenwich.','Só uma pequena parte está ao norte do Equador.','O Brasil todo está a oeste de Greenwich.'],['Brasil: hemisférios sul e oeste (uma parte no norte).'],'Uma faixa do Norte do país (Roraima, Amapá) fica no hemisfério norte.'),
'g-coord-002':(['Paralelos são paralelos ao Equador.','Círculos polares são paralelos.','Trópicos são paralelos.'],['Meridianos: polo a polo (longitude).','Paralelos: paralelos ao Equador (latitude).'],'Trópicos e círculos polares são paralelos especiais.'),
'g-coord-003':(['Círculo Polar Antártico fica perto da Antártida.','Câncer fica no hemisfério norte.','Equador passa pelo norte do Brasil.'],['Trópico de Capricórnio: passa por São Paulo.'],'Capricórnio = sul; Câncer = norte.'),
'g-coord-004':(['Tordesilhas foi uma linha de tratado, não o meridiano 0°.','Equador divide norte e sul.','Capricórnio é um paralelo.'],['Greenwich: meridiano 0°, leste × oeste.'],'Equador divide norte e sul; Greenwich divide leste e oeste.'),
'g-coord-005':(['360° é a volta toda, não a latitude.','0° a 180° leste/oeste é longitude.','Vai até 90°, não 45°.'],['Latitude: 0° a 90° N ou S.','Longitude: 0° a 180° L ou O.'],'Latitude é norte/sul; longitude é leste/oeste.'),
'g-coord-006':(['Círculo Polar Ártico é um paralelo do norte.','Câncer é paralelo do norte.','Greenwich divide leste e oeste.'],['Equador: paralelo 0°, norte × sul.'],'Equador é paralelo; Greenwich é meridiano.'),
'g-coord-007':(['Latitude não tem nada a ver com o Sol.','Mede-se a partir do Equador, não do polo.','Greenwich é a referência da longitude.'],['Latitude: a partir do Equador. Longitude: a partir de Greenwich.'],'Lat = "linha deitada" (paralelos); long = meridianos em pé.'),
'g-coord-008':(['0° a 90° N/S é a latitude.','24 é o número de fusos.','360° seria a volta toda.'],['Longitude: 0° a 180° leste ou oeste.'],'Longitude vai até 180° de cada lado: 180 + 180 = 360.'),
'g-coord-009':(['Fusos são faixas de horário.','Meridianos vão de polo a polo.','Escala é proporção do mapa.'],['Paralelos: linhas paralelas ao Equador.'],'O próprio nome entrega: paralelo é paralelo ao Equador.'),
'g-coord-010':(['Polo Norte é 90° N.','Polo Sul é 90° S.','Greenwich é longitude 0°, não latitude.'],['Latitude 0° = Equador. Longitude 0° = Greenwich.'],'Latitude 0° está no Equador, em qualquer longitude.'),
'g-mov-001':(['100 anos é um século.','24 horas é a rotação.','30 dias é cerca de um mês.'],['Translação: cerca de 365 dias e 6 horas.'],'As 6 horas a mais formam o ano bissexto.'),
'g-mov-002':(['Fases da Lua não causam estações.','Rotação causa dia e noite.','A distância muda pouco e não explica estações opostas nos hemisférios.'],['Estações: inclinação do eixo + translação.'],'Se fosse a distância, os dois hemisférios teriam verão juntos, e não têm.'),
'g-mov-003':(['Eclipse é sombra de um astro sobre outro.','Solstício é o dia mais longo ou mais curto.','Rotação é o giro da Terra.'],['Equinócio: dia = noite (início de outono e primavera).','Solstício: dia mais longo ou mais curto (início de verão e inverno).'],'Equi = igual: só o equinócio tem dia e noite iguais.'),
'g-mov-004':(['Terremotos vêm das placas tectônicas.','Estações vêm da inclinação e translação.','Marés são causadas principalmente pela Lua.'],['Rotação → dia e noite. Translação → ano e estações.'],'Rotação = dia; translação = ano.'),
'g-mov-005':(['365 dias é a translação.','30 dias não é rotação.','12 horas é só meio giro.'],['Rotação: cerca de 24 horas.'],'O dia com sol pode ter 12 h, mas a rotação completa leva 24 h.'),
'g-mov-006':(['Verão nos dois ao mesmo tempo não acontece.','Outono no norte combina com primavera no sul.','Primavera no norte combina com outono no sul.'],['Hemisférios norte e sul têm estações opostas.'],'Natal no Brasil é no verão; nos EUA, no inverno.'),
'g-mov-007':(['Equinócio tem dia e noite iguais.','Equinócio de primavera também.','Solstício de inverno é o dia mais curto.'],['Solstício de verão: dia mais longo. Solstício de inverno: dia mais curto.'],'No hemisfério sul, o solstício de verão é por volta de 21 de dezembro.'),
'g-mov-008':(['Seria o contrário se a Terra girasse para oeste.','O Sol não nasce ao norte.','O Sol parece se mover por causa da rotação.'],['Terra gira para leste → o Sol parece ir de leste para oeste.'],'Quem se mexe é a Terra; o movimento do Sol é aparente.'),
'g-mov-009':(['Não tem a ver com feriados.','A velocidade da Terra não muda em fevereiro.','A Lua não atrasa o calendário.'],['6 h × 4 anos = 24 h = 1 dia → ano bissexto.'],'Ano bissexto tem 366 dias.'),
'g-mov-010':(['90° seria um quarto da volta.','30° seriam 2 fusos.','24 é o número de fusos, não os graus.'],['360° ÷ 24 h = 15° por fuso.'],'Andando 15° para leste, o horário adianta 1 hora.'),
'g-rel-001':(['Serra é elevada e acidentada.','Montanha é muito elevada.','Planalto é elevado e predomina o desgaste.'],['Planície: plana e baixa, predomina a deposição (sedimentos chegam).','Planalto: elevado, predomina o desgaste.'],'A diferença planície × planalto não é só altura: é deposição × desgaste.'),
'g-rel-002':(['Cordilheira é conjunto de montanhas.','Planalto é elevado.','Montanha é elevada.'],['Depressão: mais baixa que o entorno.'],'Depressão relativa fica acima do nível do mar; absoluta, abaixo.'),
'g-rel-003':(['Rotação não causa terremotos.','Chuva não causa terremotos.','Vento não causa terremotos.'],['Terremotos: movimento das placas tectônicas.'],'O Brasil fica no meio de uma placa, por isso tem poucos terremotos fortes.'),
'g-rel-004':(['Árvores não "atraem" chuva para causar erosão.','O vento não diminui com o desmatamento.','O solo exposto fica mais frágil, não mais duro.'],['Sem plantas, a chuva arrasta o solo: mais erosão.'],'Raízes seguram o solo; folhas amortecem a chuva.'),
'g-rel-005':(['O núcleo é interno.','O magma é interno.','Vulcões e terremotos são agentes internos.'],['Externos: chuva, vento, rios, mar, seres vivos (desgastam).','Internos: vulcanismo e tectonismo (constroem).'],'Externo vem de fora e desgasta; interno vem de dentro e levanta.'),
'g-rel-006':(['Depressões são baixas.','Planícies são planas e baixas.','Várzeas são áreas alagáveis à beira dos rios.'],['Cordilheira: conjunto de montanhas altas (Andes, Himalaia).'],'O Brasil não tem cordilheiras como os Andes; tem serras e planaltos.'),
'g-rel-007':(['Chuva e vento são externos.','Raízes e animais são externos.','Rios e ondas são externos.'],['Internos: vulcanismo e tectonismo.'],'Tectonismo = movimento das placas.'),
'g-rel-008':(['Serra Gaúcha e Serra Geral ficam no Sul.','Espinhaço e Canastra ficam em Minas Gerais.','Carajás e Roncador ficam no Norte e Centro-Oeste.'],['Vale do Paraíba: entre a Mantiqueira e a Serra do Mar.'],'Mantiqueira fica para o lado de Minas; Serra do Mar, para o lado do litoral.'),
'g-rel-009':(['Vulcanismo é agente interno.','Tectonismo é movimento das placas.','Sedimentação é o acúmulo do material, depois do desgaste.'],['Intemperismo: rochas quebradas e decompostas pelo clima e seres vivos.'],'Intemperismo quebra a rocha no lugar; erosão leva o material embora.'),
'g-rel-010':(['Praia é litoral, baixa.','Planície é baixa e com deposição.','Depressão é mais baixa que o entorno.'],['Planalto: elevado, irregular, predomina o desgaste.'],'Grande parte do Brasil é formada por planaltos.'),
'g-agua-001':(['Barômetro mede pressão do ar.','Termômetro mede temperatura.','Anemômetro mede a velocidade do vento.'],['Pluviômetro: chuva. Anemômetro: vento. Barômetro: pressão.'],'Pluvial = chuva; anemo = vento.'),
'g-agua-002':(['Fusão é sólido → líquido.','Infiltração é a água entrando no solo.','Evaporação leva a água para cima, mas a nuvem se forma na condensação.'],['Ciclo da água: evaporação → condensação (nuvens) → precipitação → infiltração/escoamento.'],'Evaporação sobe o vapor; condensação forma a nuvem.'),
'g-agua-003':(['Tietê passa por São Paulo capital.','São Francisco passa por MG, BA e Nordeste.','Amazonas fica no Norte.'],['Paraíba do Sul: atravessa o Vale do Paraíba e SJC.'],'O rio dá nome ao Vale.'),
'g-agua-004':(['Lago é água parada.','Foz é onde o rio termina.','Lençol freático é água subterrânea.'],['Afluente: rio que deságua em outro maior.'],'Afluente "aflui" para o principal.'),
'g-agua-005':(['Geleiras têm muita água doce, mas bem menos que os oceanos.','Nuvens têm pouquíssima água.','Rios têm uma parte mínima.'],['Cerca de 97% da água está nos oceanos (salgada).'],'A maior parte da água DOCE está nas geleiras.'),
'g-agua-006':(['Planície é forma de relevo.','Nascente é o começo do rio.','Foz é o fim do rio.'],['Bacia hidrográfica: área drenada pelo rio principal e afluentes.'],'Bacia é uma região inteira, não só o rio.'),
'g-agua-007':(['Nascente é onde o rio começa.','Leito é o "chão" por onde o rio corre.','Margem é a borda do rio.'],['Nascente (começo) → leito → foz (fim).'],'Foz pode ser em outro rio, lago ou no mar.'),
'g-agua-008':(['Foz é onde termina.','Afluente é rio que deságua em outro.','Delta é um tipo de foz com vários braços.'],['Nascente: onde o rio começa.'],'Rio nasce no alto e corre para baixo, até a foz.'),
'g-agua-009':(['Polar não existe no Brasil.','Desértico não predomina; o semiárido é outro clima.','Temperado frio não predomina; o Sul tem subtropical.'],['Brasil: predomina o clima tropical.'],'Semiárido (Nordeste) não é deserto.'),
'g-agua-010':(['É o contrário: o tempo muda todo dia.','Não são a mesma coisa.','Tempo existe o ano todo.'],['Tempo: condição do momento. Clima: padrão de muitos anos.'],'"Hoje está frio" é tempo; "o inverno de SJC é seco" é clima.'),
}
